import{_ as t}from"./chunks/shop-overview.gpu4ascj.js";import{_ as r,o as a,c as o,a7 as s}from"./chunks/framework.C4ZIv4ii.js";const g=JSON.parse('{"title":"E-commerce Overview","description":"","frontmatter":{},"headers":[],"relativePath":"ecommerce/overview.md","filePath":"ecommerce/overview.md","lastUpdated":1788111091000}'),i={name:"ecommerce/overview.md"};function n(l,e,d,c,h,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="e-commerce-overview" tabindex="-1">E-commerce Overview <a class="header-anchor" href="#e-commerce-overview" aria-label="Permalink to &quot;E-commerce Overview&quot;">​</a></h1><p>Falcon CMS includes a complete e-commerce system built directly into the package — no extra plugins needed.</p><p><img src="'+t+'" alt="Shop overview"></p><p><em>Revenue, order counts and conversion, with the order-status breakdown — <strong>Admin → Shop → Overview</strong>.</em></p><div class="tip custom-block"><p class="custom-block-title">Free in the core</p><p>As of <strong>v2.2</strong>, the full e-commerce system is part of the <strong>free core</strong> — no Pro license required. Build and run a complete store on any FalconCMS site.</p></div><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Products</strong> with images, pricing, inventory, SKU, weight and dimensions</li><li><strong>Variable products</strong> — size, colour and custom options, priced per variation</li><li><strong>Product Categories &amp; Tags</strong> — dedicated, first-class taxonomy</li><li><strong>Shop filters</strong> — search, price range, category, attributes, stock and sale</li><li><strong>Shopping cart</strong> — session-based, persistent, prices re-checked against the catalogue</li><li><strong>Coupon codes</strong> — four types, see <a href="/falconcms/ecommerce/coupons.html">Coupons</a></li><li><strong>Promotions</strong> — buy-one-get-one and similar automatic offers, see <a href="/falconcms/ecommerce/promotions.html">Promotions</a></li><li><strong>Shipping</strong> — flat rate, zones, and rates banded by quantity or weight</li><li><strong>Tax</strong> — per-country rates, inclusive or exclusive pricing</li><li><strong>Checkout</strong> — guest or registered customer, with a saved address book</li><li><strong>Multiple payment gateways</strong> — PayPal, Stripe, SSLCommerz, bank transfer</li><li><strong>Order management</strong> — status workflow, invoices, refunds</li><li><strong>Product reviews</strong> with moderation</li><li><strong>Wishlist</strong></li><li><strong>Order tracking</strong> — customers track by order number + email</li><li><strong>Structured data</strong> — schema.org product markup for search results</li></ul><h2 id="setup-checklist" tabindex="-1">Setup Checklist <a class="header-anchor" href="#setup-checklist" aria-label="Permalink to &quot;Setup Checklist&quot;">​</a></h2><ol><li><p><strong>Create pages</strong> — Falcon CMS auto-creates Shop, Cart, Checkout, and Account pages during <code>falcon:install</code>. If missing, create them and assign in settings.</p></li><li><p><strong>Configure Shop Settings</strong> — Go to <strong>Admin → Shop → Settings</strong>:</p><ul><li>Currency and format</li><li>Tax rate</li><li>Shipping method and rate</li><li>Payment gateways</li></ul></li><li><p><strong>Add Products</strong> — Admin → Products → Add New</p></li><li><p><strong>Test checkout</strong> — Add a product to cart and complete a test order</p></li></ol><h2 id="shop-settings" tabindex="-1">Shop Settings <a class="header-anchor" href="#shop-settings" aria-label="Permalink to &quot;Shop Settings&quot;">​</a></h2><p>Navigate to <strong>Admin → Shop → Settings</strong>:</p><p>Settings are grouped into tabs. The common ones:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td>General</td><td>Currency</td><td>USD, EUR, BDT, GBP, etc.</td></tr><tr><td>General</td><td>Currency position</td><td>Before or after the amount</td></tr><tr><td>General</td><td>Decimal places</td><td>Price formatting (e.g. 2 → <code>$10.00</code>)</td></tr><tr><td>General</td><td>Shop / Cart / Checkout / Account page</td><td>Which page serves each role</td></tr><tr><td>General</td><td>Enable taxes</td><td>Master switch for the whole tax engine</td></tr><tr><td>Products</td><td>Manage stock</td><td>Track quantities shop-wide</td></tr><tr><td>Products</td><td>Out of stock threshold</td><td>At or below this, a product reads as sold out</td></tr><tr><td>Shipping</td><td>Flat rate, zones, free-shipping threshold</td><td>See <a href="/falconcms/ecommerce/shipping-tax.html">Shipping &amp; Tax</a></td></tr><tr><td>Tax</td><td>Rates, price entry, display</td><td>See <a href="/falconcms/ecommerce/shipping-tax.html">Shipping &amp; Tax</a></td></tr><tr><td>Coupons</td><td>Enable coupons, stacking policy</td><td>See <a href="/falconcms/ecommerce/coupons.html">Coupons</a></td></tr><tr><td>Checkout</td><td>Guest checkout, force login</td><td>Who may place an order</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Shipping and tax are more capable than a single rate — zones, per-country tax and inclusive/exclusive pricing each have their own page.</p></div><h2 id="payment-gateways" tabindex="-1">Payment Gateways <a class="header-anchor" href="#payment-gateways" aria-label="Permalink to &quot;Payment Gateways&quot;">​</a></h2><h3 id="paypal" tabindex="-1">PayPal <a class="header-anchor" href="#paypal" aria-label="Permalink to &quot;PayPal&quot;">​</a></h3><ol><li>Go to <strong>Admin → Settings → Integrations</strong></li><li>Enable PayPal</li><li>Enter Client ID and Secret (from PayPal Developer Dashboard)</li><li>Select Sandbox / Live mode</li></ol><h3 id="stripe" tabindex="-1">Stripe <a class="header-anchor" href="#stripe" aria-label="Permalink to &quot;Stripe&quot;">​</a></h3><ol><li>Enable Stripe in Integrations settings</li><li>Enter Public Key and Secret Key (from Stripe Dashboard)</li></ol><h3 id="sslcommerz-south-asia" tabindex="-1">SSLCommerz (South Asia) <a class="header-anchor" href="#sslcommerz-south-asia" aria-label="Permalink to &quot;SSLCommerz (South Asia)&quot;">​</a></h3><ol><li>Enable SSLCommerz</li><li>Enter Store ID and Signature Key</li></ol><h2 id="shop-dashboard" tabindex="-1">Shop Dashboard <a class="header-anchor" href="#shop-dashboard" aria-label="Permalink to &quot;Shop Dashboard&quot;">​</a></h2><p><strong>Admin → Shop → Overview</strong> shows:</p><ul><li>Total Orders</li><li>Net Revenue (gross minus refunds)</li><li>Gross Revenue</li><li>Total Refunded</li><li>Average Order Value</li><li>Order status breakdown chart</li></ul><p>All stats are filterable by: Today, Last 7 days, Last 30 days, This month, This year, All time, Custom range.</p>',25)])])}const S=r(i,[["render",n]]);export{g as __pageData,S as default};
